import React, { useState, useEffect } from "react";

export default function CodeExplainer() {
  const [room, setRoom] = useState("0I6PXI");
  const [code, setCode] = useState("");
  const [prompt, setPrompt] = useState("explain");
  const [comment, setComment] = useState("");
  const [comments, setComments] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [explanation, setExplanation] = useState("");

  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const roomCode = urlParams.get('room');
    if (roomCode) setRoom(roomCode);
  }, []);

  const handleExplain = async () => {
    if (!code.trim()) {
      alert("Please paste your code first!");
      return;
    }
    
    setIsLoading(true);
    setTimeout(() => {
      setExplanation(`**Code Analysis:**\n\nYour code has ${code.split('\n').length} lines and ${code.length} characters.\n\n**Key Points:**\n• Functions detected: ${code.match(/function/g)?.length || 0}\n• Variables: ${code.match(/\b(let|const|var)\s+/g)?.length || 0}\n\n**Suggestions:**\n• Add error handling\n• Consider code optimization\n• Use modern ES6+ features`);
      setIsLoading(false);
    }, 1500);
  };

  const handleSendComment = () => {
    if (!comment.trim()) return;
    setComments([...comments, {
      id: Date.now(),
      text: comment,
      timestamp: new Date().toLocaleTimeString()
    }]);
    setComment("");
  };

  return (
    <div
      style={{
        minHeight: "100vh",
        background: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)",
        padding: "20px",
        fontFamily: "'Inter', -apple-system, sans-serif",
      }}
    >
      <div
        style={{
          maxWidth: "1400px",
          margin: "0 auto",
        }}
      >
        {/* Header */}
        <div
          style={{
            background: "#1a1a1a",
            borderRadius: "16px 16px 0 0",
            padding: "25px 30px",
            border: "1px solid rgba(255,255,255,0.1)",
            borderBottom: "none",
          }}
        >
          <h1 style={{ fontSize: "24px", fontWeight: 700, color: "#fff", margin: 0, marginBottom: "5px" }}>
            Code Explainer (Gemini + FastAPI)
          </h1>
          <p style={{ color: "#888", fontSize: "14px", margin: 0 }}>
            Room: <span style={{ color: "#667eea", fontWeight: 600 }}>{room}</span>
          </p>
        </div>

        {/* Main Content */}
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "2fr 1fr",
            gap: "0",
            background: "#1a1a1a",
            border: "1px solid rgba(255,255,255,0.1)",
          }}
        >
          {/* Left - Code Editor */}
          <div style={{ borderRight: "1px solid rgba(255,255,255,0.1)", display: "flex", flexDirection: "column" }}>
            <textarea
              value={code}
              onChange={(e) => setCode(e.target.value)}
              placeholder="Paste your code here"
              style={{
                width: "100%",
                height: "400px",
                background: "#0d0d0d",
                border: "none",
                padding: "25px",
                color: "#e0e0e0",
                fontSize: "14px",
                fontFamily: "'Fira Code', 'Courier New', monospace",
                resize: "none",
                outline: "none",
                lineHeight: "1.6",
              }}
            />

            {/* Explanation Box */}
            {explanation && (
              <div
                style={{
                  padding: "25px",
                  background: "#0f0f0f",
                  borderTop: "1px solid rgba(255,255,255,0.1)",
                  maxHeight: "300px",
                  overflowY: "auto",
                }}
              >
                <h3 style={{ color: "#667eea", fontSize: "16px", marginBottom: "15px", fontWeight: 600 }}>
                  ✨ AI Explanation
                </h3>
                <pre
                  style={{
                    color: "#e0e0e0",
                    fontSize: "13px",
                    lineHeight: "1.7",
                    margin: 0,
                    whiteSpace: "pre-wrap",
                    fontFamily: "'Inter', sans-serif",
                  }}
                >
                  {explanation}
                </pre>
              </div>
            )}
          </div>

          {/* Right - Comments */}
          <div style={{ display: "flex", flexDirection: "column", height: "400px" }}>
            <div
              style={{
                padding: "20px",
                borderBottom: "1px solid rgba(255,255,255,0.1)",
                background: "#1f1f1f",
              }}
            >
              <h3 style={{ color: "#fff", fontSize: "16px", margin: 0, fontWeight: 600 }}>Comments</h3>
            </div>

            <div
              style={{
                flex: 1,
                padding: "20px",
                overflowY: "auto",
                background: "#0d0d0d",
              }}
            >
              {comments.length === 0 ? (
                <p style={{ color: "#666", fontSize: "14px", textAlign: "center", paddingTop: "40px" }}>
                  No comments yet
                </p>
              ) : (
                comments.map((c) => (
                  <div
                    key={c.id}
                    style={{
                      background: "#1a1a1a",
                      borderRadius: "8px",
                      padding: "12px",
                      marginBottom: "10px",
                      border: "1px solid rgba(255,255,255,0.05)",
                    }}
                  >
                    <p style={{ color: "#e0e0e0", fontSize: "13px", margin: 0, marginBottom: "5px" }}>
                      {c.text}
                    </p>
                    <p style={{ color: "#666", fontSize: "11px", margin: 0 }}>{c.timestamp}</p>
                  </div>
                ))
              )}
            </div>

            <div
              style={{
                padding: "15px",
                background: "#1f1f1f",
                borderTop: "1px solid rgba(255,255,255,0.1)",
              }}
            >
              <input
                type="text"
                value={comment}
                onChange={(e) => setComment(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && handleSendComment()}
                placeholder="Write a comment..."
                style={{
                  width: "100%",
                  padding: "10px 12px",
                  background: "#0d0d0d",
                  border: "1px solid rgba(255,255,255,0.1)",
                  borderRadius: "6px",
                  color: "#e0e0e0",
                  fontSize: "13px",
                  outline: "none",
                  marginBottom: "8px",
                }}
              />
              <button
                onClick={handleSendComment}
                style={{
                  width: "100%",
                  padding: "10px",
                  background: "#3b82f6",
                  border: "none",
                  borderRadius: "6px",
                  color: "#fff",
                  fontSize: "13px",
                  fontWeight: 600,
                  cursor: "pointer",
                }}
              >
                Send
              </button>
            </div>

            <p style={{ color: "#666", fontSize: "12px", padding: "10px 15px", margin: 0, background: "#0d0d0d" }}>
              Joined room: {room}
            </p>
          </div>
        </div>

        {/* Bottom Bar */}
        <div
          style={{
            background: "#1a1a1a",
            borderRadius: "0 0 16px 16px",
            padding: "20px 30px",
            border: "1px solid rgba(255,255,255,0.1)",
            borderTop: "none",
            display: "flex",
            gap: "15px",
          }}
        >
          <input
            type="text"
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleExplain()}
            placeholder="explain"
            style={{
              flex: 1,
              padding: "12px 18px",
              background: "#0d0d0d",
              border: "1px solid rgba(255,255,255,0.1)",
              borderRadius: "8px",
              color: "#e0e0e0",
              fontSize: "14px",
              outline: "none",
            }}
          />
          <button
            onClick={handleExplain}
            disabled={isLoading}
            style={{
              padding: "12px 30px",
              background: isLoading ? "#555" : "#3b82f6",
              border: "none",
              borderRadius: "8px",
              color: "#fff",
              fontSize: "14px",
              fontWeight: 600,
              cursor: isLoading ? "not-allowed" : "pointer",
            }}
          >
            {isLoading ? "Loading..." : "Send"}
          </button>
        </div>
      </div>
    </div>
  );
}
